    AbilityPower?: number | undefined;
    MaxAbilityPower?: number | undefined;
    AllowedWeapons?: string[] | undefined;
    Footstep?: boolean | undefined;
    OldWalkSpeed?: number | undefined;
    selfOldRunSpeed?: number | undefined;
    LastDamage?: number | undefined;
    TotalDamage?: number | undefined;
    Talking?: boolean | undefined;
    AmmoPacks?: number | undefined;
    Battery?: number | undefined;
    MaxCharge?: number | undefined;
    Breath?: number | undefined;
    MaxBreath?: number | undefined;
    Nightvision?: boolean | undefined;
    PrimaryWeapon?: ZPRegisteredWeapon | undefined;
    SecondaryWeapon?: ZPRegisteredWeapon | undefined;
