    ScreenFilter?: GLuaColor | undefined;
    Points?: number | undefined;
    CamouflageZombieWeapon?: string | undefined;
    SetZombieClass(this: ZPServerPlayer, ZombieClass: ZPClassDefinition): void;
    GetZombieClass(this: ZPServerPlayer): ZPClassDefinition;
    SetNextZombieClass(this: ZPServerPlayer, NextZombieClass: ZPClassDefinition): void;
    GetNextZombieClass(this: ZPServerPlayer): ZPClassDefinition | undefined;
    SetHumanClass(this: ZPServerPlayer, HumanClass: ZPClassDefinition): void;
