    TakeAmmoPacks(this: ZPServerPlayer, Amount: number): void;
    SetAmmoPacks(this: ZPServerPlayer, AmmoPacks: number, NotSave?: boolean): void;
    GetAmmoPacks(this: ZPServerPlayer): number;
    ChargeBattery(this: ZPServerPlayer, Amount: number): void;
    DrainBattery(this: ZPServerPlayer, Amount: number): void;
    SetBattery(this: ZPServerPlayer, Battery: number): void;
    GetBattery(this: ZPServerPlayer): number;
    SetMaxBatteryCharge(this: ZPServerPlayer, MaxCharge: number): void;
    GetMaxBatteryCharge(this: ZPServerPlayer): number;
    AddBreath(this: ZPServerPlayer, Breath: number): void;
