    GetPrimaryWeaponGiven(this: ZPServerPlayer): boolean;
    SetSecondaryWeaponGiven(this: ZPServerPlayer, SecondaryWeaponGiven: boolean): void;
    GetSecondaryWeaponGiven(this: ZPServerPlayer): boolean;
    SetMeleeWeapon(this: ZPServerPlayer, MeleeWeapon: ZPRegisteredWeapon | undefined): void;
    GetMeleeWeapon(this: ZPServerPlayer): ZPRegisteredWeapon | undefined;
    SetMeleeWeaponGiven(this: ZPServerPlayer, MeleeWeaponGiven: boolean): void;
    GetMeleeWeaponGiven(this: ZPServerPlayer): boolean;
