    GetLastMove(this: ZPServerPlayer): number;
    MoveSpectateID(this: ZPServerPlayer, Move: number, Players: ZPServerPlayer[]): void;
    GetSpectateID(this: ZPServerPlayer): number;
    SetAuxGravity(this: ZPServerPlayer, AuxGravity: number): void;
    GetAuxGravity(this: ZPServerPlayer): number;
    Infect(this: ZPServerPlayer, SilentInfection?: boolean): void;
    MakeHuman(this: ZPServerPlayer): void;
    SetDamageAmplifier(this: ZPServerPlayer, DamageAmplifier: number): void;
    GetDamageAmplifier(this: ZPServerPlayer): number;
    Cure(this: ZPServerPlayer): void;
