    GetLight(this: ZPServerPlayer): GLuaColor | undefined;
    SetScreenFilter(this: ZPServerPlayer, ScreenFilter: GLuaColor | undefined): void;
    AddPoints(this: ZPServerPlayer, PointsToAdd: number): void;
    RemovePoints(this: ZPServerPlayer, PointsToRemove: number): void;
    SetPoints(this: ZPServerPlayer, Points: number): void;
    GetPoints(this: ZPServerPlayer): number;
